import ipaddress
import logging
import socket
from collections.abc import Sequence

import httpx
from curl_cffi import CurlOpt
from httpx_curl_cffi import AsyncCurlTransport, CurlTransport

_IPAddress = ipaddress.IPv4Address | ipaddress.IPv6Address
_IPNetwork = ipaddress.IPv4Network | ipaddress.IPv6Network

_CGNAT = ipaddress.ip_network("100.64.0.0/10")


class ForcedTimeoutException(Exception):
    """
    Raised when a request takes longer than the timeout value.
    """

    ...


class InvalidDomainError(Exception):
    """
    Raised when a request is made to a local IP address.
    """

    ...


def _normalize(ip: _IPAddress) -> _IPAddress:
    if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped is not None:
        return ip.ipv4_mapped
    return ip


def is_blocked_ip(ip: _IPAddress) -> bool:
    """True for addresses that are never reachable unless explicitly allowed."""
    ip = _normalize(ip)
    return bool(
        ip.is_private
        or ip.is_loopback
        or ip.is_link_local
        or ip.is_multicast
        or ip.is_reserved
        or ip.is_unspecified
        or (isinstance(ip, ipaddress.IPv4Address) and ip in _CGNAT)
    )


def _parse_entries(entries: Sequence[str]) -> tuple[set[str], list[_IPNetwork]]:
    names: set[str] = set()
    nets: list[_IPNetwork] = []
    for raw in entries:
        entry = raw.strip()
        if not entry:
            continue
        try:
            nets.append(ipaddress.ip_network(entry, strict=False))
        except ValueError:
            names.add(entry.lower().rstrip("."))
    return names, nets


def _in_nets(ip: _IPAddress, nets: list[_IPNetwork]) -> bool:
    for candidate in (ip, _normalize(ip)):
        for net in nets:
            if candidate.version == net.version and candidate in net:
                return True
    return False


class _SafeMixin:
    """Request validation and DNS pinning shared by the sync and async transports."""

    def _init_safe(
        self,
        log: logging.Logger | None,
        allow_hosts: Sequence[str],
        deny_hosts: Sequence[str],
        timeout: int,
    ) -> None:
        self._log = log
        self.timeout = timeout
        self._allow_names, self._allow_nets = _parse_entries(allow_hosts)
        self._deny_names, self._deny_nets = _parse_entries(deny_hosts)

    def _warn(self, msg: str) -> None:
        if self._log:
            self._log.warning(msg)

    def _validate(self, request: httpx.Request) -> list[str] | None:
        host = request.url.host
        lowered = host.lower().rstrip(".")
        port = request.url.port or (443 if request.url.scheme == "https" else 80)

        literal: _IPAddress | None
        try:
            literal = ipaddress.ip_address(host.strip("[]").split("%")[0])
        except ValueError:
            literal = None

        addresses: list[_IPAddress] = []
        if literal is not None:
            addresses.append(literal)
        else:
            try:
                infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
            except (socket.gaierror, UnicodeError) as e:
                raise InvalidDomainError(f"could not resolve host {host!r}: {e}") from e
            for info in infos:
                addr = ipaddress.ip_address(str(info[4][0]).split("%")[0])
                if addr not in addresses:
                    addresses.append(addr)
            if not addresses:
                raise InvalidDomainError(f"could not resolve host {host!r}")

        if lowered in self._deny_names or any(_in_nets(a, self._deny_nets) for a in addresses):
            self._warn(f"request to disallowed host blocked: {request.url}")
            raise InvalidDomainError(f"request to disallowed host: {host}")

        allowed = lowered in self._allow_names or any(_in_nets(a, self._allow_nets) for a in addresses)
        if not allowed:
            for addr in addresses:
                if is_blocked_ip(addr):
                    self._warn(f"invalid request on local resource: {request.url} -> {addr}")
                    raise InvalidDomainError(f"invalid request on local resource: {request.url} -> {addr}")

        if literal is not None:
            return None
        return [f"{host}:{port}:{a}" for a in addresses]

    def _apply_pin(self, entries: list[str] | None) -> None:
        options = self._session.curl_options  # type: ignore[attr-defined]
        if entries is None:
            options.pop(CurlOpt.RESOLVE, None)
        else:
            options[CurlOpt.RESOLVE] = entries

    def _prepare(self, request: httpx.Request) -> None:
        # override timeout value for _all_ requests
        request.extensions["timeout"] = httpx.Timeout(self.timeout, pool=self.timeout).as_dict()
        self._apply_pin(self._validate(request))


class AsyncSafeTransport(_SafeMixin, AsyncCurlTransport):
    """
    httpx-curl-cffi transport that enforces a timeout, validates every request against the address
    policy and pins the connection to the validated addresses (preventing DNS rebinding).
    """

    def __init__(
        self,
        *,
        log: logging.Logger | None = None,
        allow_hosts: Sequence[str] = (),
        deny_hosts: Sequence[str] = (),
        timeout: int = 15,
        **kwargs,
    ):
        self._init_safe(log, allow_hosts, deny_hosts, timeout)
        super().__init__(**kwargs)

    async def handle_async_request(self, request: httpx.Request) -> httpx.Response:
        self._prepare(request)
        return await super().handle_async_request(request)


class SafeTransport(_SafeMixin, CurlTransport):
    """Sync counterpart of AsyncSafeTransport."""

    def __init__(
        self,
        *,
        log: logging.Logger | None = None,
        allow_hosts: Sequence[str] = (),
        deny_hosts: Sequence[str] = (),
        timeout: int = 15,
        **kwargs,
    ):
        self._init_safe(log, allow_hosts, deny_hosts, timeout)
        super().__init__(**kwargs)

    def handle_request(self, request: httpx.Request) -> httpx.Response:
        self._prepare(request)
        return super().handle_request(request)


def post(
    url: str,
    *,
    json=None,
    timeout: int = 15,
    allow_hosts: Sequence[str] = (),
    deny_hosts: Sequence[str] = (),
    **kwargs,
) -> httpx.Response:
    """Sync POST through SafeTransport, following redirects (each hop is validated)."""
    transport = SafeTransport(allow_hosts=allow_hosts, deny_hosts=deny_hosts, timeout=timeout)
    try:
        with httpx.Client(transport=transport, follow_redirects=True, timeout=timeout) as client:
            return client.post(url, json=json, **kwargs)
    finally:
        transport.close()

